import { markLocalTaskSolved } from "@hunt/puzzle-components";
import React, { useState } from "react";
import {
  type CellState,
  checkNonogramSolution,
  COL_CLUES,
  GRID_SIZE,
  ROW_CLUES,
} from "./shared";

type NonogramProps = {
  onVerify?: (isVerified: boolean) => void;
};

/**
 * Main App Component for the Nonogram Game.
 */
export const Nonogram: React.FC<NonogramProps> = ({ onVerify }) => {
  // State for the user's current grid progress.
  const [grid, setGrid] = useState<CellState[][]>(
    Array.from({ length: GRID_SIZE }, () =>
      Array<CellState>(GRID_SIZE).fill("EMPTY"),
    ),
  );
  // State to track if the puzzle has been successfully solved.
  const [isSolved, setIsSolved] = useState(false);

  /**
   * Handles user clicks on a grid cell, cycling through states: EMPTY -> FILLED -> CROSSED.
   * @param row - The row index of the clicked cell.
   * @param col - The column index of the clicked cell.
   */
  const handleCellClick = (row: number, col: number) => {
    // Prevent interaction if the puzzle is already solved.
    if (isSolved) return;

    // Create a new grid copy to avoid direct state mutation.
    const newGrid = grid.map((r) => [...r]);
    const currentCell = newGrid[row][col];

    // Cycle through the cell states.
    if (currentCell === "EMPTY") {
      newGrid[row][col] = "FILLED";
    } else if (currentCell === "FILLED") {
      newGrid[row][col] = "CROSSED";
    } else {
      newGrid[row][col] = "EMPTY";
    }

    setGrid(newGrid);
    checkSolution(newGrid);
  };

  /**
   * Checks if the current grid state matches the puzzle's solution.
   * @param currentGrid - The current state of the game grid.
   */
  const checkSolution = (currentGrid: CellState[][]) => {
    // Use the shared validation function
    if (!checkNonogramSolution(currentGrid, (cell) => cell === "FILLED")) {
      return; // Validation failed, puzzle not solved yet
    }

    // If validation passed, verify locally
    setIsSolved(true);
    onVerify?.(true);
    markLocalTaskSolved("puzzmon_picross");
  };

  /**
   * Resets the game to its initial state, clearing the grid.
   */
  const handleReset = () => {
    setGrid(
      Array.from({ length: GRID_SIZE }, () =>
        Array<CellState>(GRID_SIZE).fill("EMPTY"),
      ),
    );
    setIsSolved(false);
  };
  return (
    <div className="flex flex-col items-center justify-center gap-5 p-10 px-5 font-sans bg-gray-100 rounded-xl min-h-screen">
      {isSolved && (
        <div className="px-6 py-3 font-bold text-green-800 bg-green-100 border border-green-200 rounded-lg">
          🎉 You Solved It! 🎉
        </div>
      )}
      <div className="grid grid-cols-[auto_1fr] grid-rows-[auto_1fr] gap-1.5 p-3 bg-white rounded-lg shadow-lg">
        <div /> {/* Top-left empty corner */}
        {/* Column Clues */}
        <div className="flex items-end justify-around p-1 bg-gray-200 rounded-md col-start-2 row-start-1 pb-3">
          {COL_CLUES.map((clue, index) => (
            <div
              key={index}
              className="flex flex-col items-center justify-end min-w-[32px] min-h-[32px] gap-1 font-bold text-center text-gray-700"
            >
              {clue.map((c, i) => (
                <div key={i}>{c}</div>
              ))}
            </div>
          ))}
        </div>
        {/* Row Clues */}
        <div className="flex flex-col items-end justify-around p-1 bg-gray-200 rounded-md col-start-1 pr-3">
          {ROW_CLUES.map((clue, index) => (
            <div
              key={index}
              className="flex items-center justify-end min-w-[32px] min-h-[32px] gap-2 font-bold text-center text-gray-700"
            >
              {clue.map((c, i) => (
                <div key={i}>{c}</div>
              ))}
            </div>
          ))}
        </div>
        {/* Game Grid */}
        <div
          className="grid bg-gray-400 border-2 border-gray-800 gap-[1px]"
          style={{ gridTemplateColumns: `repeat(${GRID_SIZE}, 1fr)` }}
        >
          {grid.map((row, rIndex) =>
            row.map((cell, cIndex) => (
              <button
                key={`${rIndex}-${cIndex}`}
                onClick={() => {
                  handleCellClick(rIndex, cIndex);
                }}
                type="button"
                className={`
                                    w-8 h-8 flex justify-center items-center border border-gray-300 
                                    transition-colors duration-150 ease-in-out
                                    ${cell === "FILLED" ? "bg-gray-800" : "bg-white"}
                                    ${isSolved ? "cursor-not-allowed" : "cursor-pointer"}
                                    ${(cIndex + 1) % 5 === 0 ? "border-r-2 border-r-gray-800" : ""}
                                    ${(rIndex + 1) % 5 === 0 ? "border-b-2 border-b-gray-800" : ""}
                                `}
              >
                {cell === "CROSSED" && (
                  <span className="text-2xl leading-none text-gray-600">×</span>
                )}
              </button>
            )),
          )}
        </div>
      </div>

      {!isSolved && (
        <button
          onClick={handleReset}
          className="px-6 py-3 text-base font-bold text-white bg-blue-500 border-none rounded-lg cursor-pointer transition-colors hover:bg-blue-600"
        >
          Reset
        </button>
      )}
    </div>
  );
};
