import { createRoot } from "react-dom/client";
import { Nonogram } from "./NonogramComponent";

const nonogram_elem = document.getElementById("nonogram-root");
if (nonogram_elem) {
  const root = createRoot(nonogram_elem);
  root.render(<Nonogram />);
} else {
  console.error(
    "Could not mount because #nonogram-root was nowhere to be found",
  );
}
